"""End-to-end run: build tensors from an expanded ticker universe (S&P 500 +400 + 600), binarize labels at a chosen percentile cutoff, train the LSTMwith early stopping, evaluate with MCC/AUC/precision/recall across thresholds."""import numpy as npfrom sklearn.metrics import matthews_corrcoef, roc_auc_scorefrom src.build_train_test_tensor import buildTrainTestTensorfrom src.lstm_model import train_modelfrom src.expanded_universe import expandedTickerUniverse# ---- config ----CUTOFF_PERCENTILE = 75  # of TRAIN labels only# ---- 0) build the expanded ticker universe ----tickers = expandedTickerUniverse().tolist()print(f"Using {len(tickers)} tickers")# ---- 1) build tensors + continuous labels ----# uses priceHistoryBatchChunked internally now, so this pulls in smaller# batches with pauses between them rather than one huge requestresult = buildTrainTestTensor(    Tickers=tickers,    start_date='1995-01-01',    end_date='2023-01-01',    test_interval=5,    matrix_length=20,    chunk_size=100,    pause_seconds=5,)print(f"train examples: {result.train_tensor.shape[0]}, test examples: {result.test_tensor.shape[0]}")# ---- 2) binarize labels using a cutoff computed from TRAIN only ----cutoff = np.percentile(result.train_labels, CUTOFF_PERCENTILE)print(f"cutoff ({CUTOFF_PERCENTILE}th percentile of train_labels): {cutoff:.4f}")train_labels_binary = (result.train_labels > cutoff).astype(np.float32)test_labels_binary = (result.test_labels > cutoff).astype(np.float32)print(f"train positive rate: {train_labels_binary.mean():.3f}  "      f"({int(train_labels_binary.sum())} / {len(train_labels_binary)})")print(f"test positive rate:  {test_labels_binary.mean():.3f}  "      f"({int(test_labels_binary.sum())} / {len(test_labels_binary)})")# ---- 3) train ----model, test_probs = train_model(    train_tensor=result.train_tensor,    train_labels=train_labels_binary,    test_tensor=result.test_tensor,    test_labels=test_labels_binary,    hidden_size=32,    num_layers=1,    dropout=0.0,    learning_rate=0.001,    batch_size=32,    num_epochs=50,    weight_decay=0.0,    patience=5,)# ---- 4) evaluate across several thresholds, not just 0.5 ----print("\n" + "=" * 60)print("EVALUATION")print("=" * 60)if len(np.unique(test_labels_binary)) < 2:    print("WARNING: test_labels_binary has only one class present, "          "AUC/MCC will not be meaningful.")else:    auc = roc_auc_score(test_labels_binary, test_probs)    print(f"AUC (threshold-independent): {auc:.4f}\n")    print(f"{'threshold':>10} {'n_pred_pos':>11} {'precision':>10} {'recall':>8} {'mcc':>8}")    for threshold in [0.5, 0.4, 0.3, 0.2, 0.1]:        preds = (test_probs > threshold).astype(int)        n_pred_pos = preds.sum()        if n_pred_pos == 0:            print(f"{threshold:>10.2f} {n_pred_pos:>11} {'--':>10} {'--':>8} {'--':>8}  (no positive predictions)")            continue        tp = ((preds == 1) & (test_labels_binary == 1)).sum()        precision = tp / n_pred_pos        recall = tp / test_labels_binary.sum()        mcc = matthews_corrcoef(test_labels_binary, preds)        print(f"{threshold:>10.2f} {n_pred_pos:>11} {precision:>10.3f} {recall:>8.3f} {mcc:>8.4f}")